ALTER TABLE rental_documents ADD COLUMN document_date DATE NULL, ADD COLUMN start_date DATE NULL, ADD COLUMN end_date DATE NULL, ADD COLUMN amount DECIMAL(20,2) NULL, ADD COLUMN return_to VARCHAR(40) NULL, ADD COLUMN reason TEXT NULL, ADD COLUMN applied BOOLEAN NOT NULL DEFAULT FALSE;
CREATE TABLE IF NOT EXISTS document_terms (id BIGINT AUTO_INCREMENT PRIMARY KEY, document_id BIGINT NOT NULL, object_id BIGINT NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, amount DECIMAL(20,2) NOT NULL, FOREIGN KEY(document_id) REFERENCES rental_documents(id), FOREIGN KEY(object_id) REFERENCES rental_objects(id));
CREATE TABLE IF NOT EXISTS rental_template_versions (template_id BIGINT NOT NULL, version INT NOT NULL, body LONGTEXT, status VARCHAR(40) NOT NULL, author_id BIGINT UNSIGNED NULL, approver_id BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(template_id,version), FOREIGN KEY(template_id) REFERENCES rental_templates(id));
INSERT IGNORE INTO rental_template_versions(template_id,version,body,status) SELECT id,version,body,status FROM rental_templates;
ALTER TABLE contracts ADD COLUMN finance_review BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN legal_review BOOLEAN NOT NULL DEFAULT FALSE, ADD COLUMN return_confirmed DATE NULL;
CREATE TABLE IF NOT EXISTS rental_schedule_runs (run_key VARCHAR(180) PRIMARY KEY, action VARCHAR(80) NOT NULL, details_json JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rental_object_periods (id BIGINT AUTO_INCREMENT PRIMARY KEY, object_id BIGINT NOT NULL, active BOOLEAN NOT NULL, started_on DATE NOT NULL, ended_on DATE NULL, reason TEXT, FOREIGN KEY(object_id) REFERENCES rental_objects(id));
